package com.fixmer.mared.technology.server.setup;
import com.fixmer.mared.gui2.framework.screen.MaredScreen;import com.google.gson.*;
import net.minecraft.client.gui.GuiGraphics;import net.minecraft.client.gui.components.*;import net.minecraft.client.gui.screens.*;import net.minecraft.network.chat.Component;
import java.nio.file.*;import java.util.*;
/** One native panel: host-only paths never become remote payload paths. */
public final class DedicatedPanelScreen75 extends MaredScreen {
 private final Screen previous;private JsonObject prefs;private boolean host;private int page;private EditBox source,root,export,mods,label;private int left,w,top,bottom,scroll,maxScroll;private final List<Button> actions=new ArrayList<>();private final List<EditBox> paths=new ArrayList<>();private final Map<Button,String> gated88=new IdentityHashMap<>();
 public DedicatedPanelScreen75(Screen previous){super(tr("title"));this.previous=previous;prefs=DedicatedPanelService75.preferences();host=!DedicatedPanelService75.hasRemote();page=host&&pref("root","").isBlank()?1:0;}
 private static Component tr(String key,Object...args){return Component.translatable("mared.dedicated75."+key,args);}
 private String pref(String k,String fallback){try{return prefs.get(k).getAsString();}catch(Exception bad){return fallback;}}
 private EditBox field(String key,int y,int max,String value,boolean path){EditBox box=addRenderableWidget(new EditBox(font,left+104,y,w-104-(path?34:0),20,tr(key)));box.setMaxLength(max);box.setValue(value);if(path){paths.add(box);addRenderableWidget(Button.builder(Component.literal("…"),b->browse(box)).bounds(left+w-30,y,30,20).build());}return box;}
 private Button button(String key,int x,int y,int width,Runnable fn){Button b=addRenderableWidget(Button.builder(tr(key),a->fn.run()).bounds(x,y,width,20).build());actions.add(b);return b;}
 private Button admin88(String key,int x,int y,int width,String operation,Runnable fn){Button b=button(key,x,y,width,fn);gated88.put(b,operation);return b;}
 @Override protected void init(){if(root!=null)collect();paths.clear();actions.clear();gated88.clear();w=Math.max(250,Math.min(660,width-24));left=(width-w)/2;int y=34;
  button(host?"host":"remote",left,y,(w-4)/2,()->{collect();host=!host;page=0;rebuildWidgets();});button("page."+page,left+(w+4)/2,y,(w-4)/2,()->{collect();page=(page+1)%3;rebuildWidgets();});y+=24;
  if(host&&page==1){source=field("source",y,4096,pref("source",""),true);y+=24;root=field("root",y,4096,pref("root",""),true);y+=24;export=field("export",y,4096,pref("export",""),true);y+=24;mods=field("mods",y,4096,pref("mods",""),true);y+=24;}
  else{source=root=export=mods=null;}
  if(page!=2){label=field("label",y,40,pref("label","r1"),false);y+=26;}else label=null;int bw=(w-8)/3;
  if(host&&page==1){button("import",left,y,bw,()->runHost("init"));button("start",left+bw+4,y,bw,()->runHost("run"));button("publication79",left+2*(bw+4),y,bw,()->{collect();minecraft.setScreen(new PublicationScreen79(this,pref("root","")));});y+=24;}
  if(page==0){admin88("stage",left,y,bw,"STAGE",()->action("STAGE"));admin88("offer",left+bw+4,y,bw,"OFFER",()->action("OFFER"));admin88("commit",left+2*(bw+4),y,bw,"COMMIT",()->confirm("commit_confirm",()->action("COMMIT")));y+=24;
  admin88("cancel",left,y,bw,"CANCEL",()->action("CANCEL"));admin88("close_round",left+bw+4,y,bw,"CLOSE",()->confirm("close_confirm",()->action("CLOSE")));admin88("stop",left+2*(bw+4),y,bw,"SHUTDOWN",()->confirm("stop_confirm",()->action("SHUTDOWN")));y+=24;
  admin88("offline_short81",left,y,(w-4)/2,"LOCAL_TEST_ON",()->confirm("offline_confirm",()->action("LOCAL_TEST_ON")));button("transition81",left+(w+4)/2,y,(w-4)/2,()->{collect();minecraft.setScreen(new TransitionScreen81(this,host,pref("root",""),pref("label","r1")));});y+=24;}if(!host&&page==2){button("access88",left,y,w,()->minecraft.setScreen(new ServerAccessScreen88(this)));y+=24;}top=y+3;bottom=height-(host&&page==2?82:34);if(host&&page==2){button("recovery77",left,height-74,w,()->{collect();minecraft.setScreen(new RecoveryScreen77(this,pref("root",""),created->{prefs.addProperty("root",created);if(root!=null)root.setValue(created);DedicatedPanelService75.save(prefs);}));});}if(host&&page==2)button("publication80",left,height-50,(w-4)/2,()->{collect();minecraft.setScreen(new PublicationHealthScreen80(this,pref("root",""),created->{prefs.addProperty("root",created);DedicatedPanelService75.save(prefs);}));});if(host&&page==2)button("https78",left+(w+4)/2,height-50,(w-4)/2,()->{collect();minecraft.setScreen(new HttpsScreen78(this,pref("root","")));});button("back",left,height-26,w,this::onClose);refresh();
 }
 private void collect(){if(label!=null)prefs.addProperty("label",label.getValue().trim());if(root!=null){prefs.addProperty("root",root.getValue().trim());prefs.addProperty("source",source.getValue().trim());prefs.addProperty("export",export.getValue().trim());prefs.addProperty("mods",mods.getValue().trim());}DedicatedPanelService75.save(prefs);}
 private void browse(EditBox box){collect();Path initial;try{initial=box.getValue().isBlank()?minecraft.gameDirectory.toPath():Path.of(box.getValue());}catch(Exception e){initial=minecraft.gameDirectory.toPath();}minecraft.setScreen(new LocalPickerScreen68(this,true,initial,path->{box.setValue(path.toString());collect();}));}
 private void confirm(String key,Runnable fn){collect();minecraft.setScreen(new ConfirmScreen(yes->{minecraft.setScreen(this);if(yes)fn.run();},tr("confirm_title"),tr(key)));}
 private void runHost(String op){collect();DedicatedPanelService75.host(op,pref("root",""),op.equals("author")?pref("export",""):pref("source",""),pref("mods",""),pref("label","r1"));}
 private void action(String op){collect();if(host)DedicatedPanelService75.host("command",pref("root",""),op.equals("SHUTDOWN")?"stop":op.toLowerCase(Locale.ROOT).replace('_','-'),"",pref("label","r1"));else DedicatedPanelService75.request(op,pref("label","r1"));}
 private void refresh(){boolean busy=DedicatedPanelService75.busy();for(Button b:actions)b.active=!busy&&(host||!gated88.containsKey(b)||DedicatedPanelService75.canRemote88(gated88.get(b)));for(EditBox e:paths)e.setEditable(!busy);if(host&&root!=null){String value=DedicatedPanelService75.preferences().has("root")?DedicatedPanelService75.preferences().get("root").getAsString():"";if(root.getValue().isBlank()&&!value.isBlank())root.setValue(value);}}
 @Override public void tick(){refresh();DedicatedPanelService75.poll(host,root==null?pref("root",""):root.getValue().trim());}
 @Override public void removed(){collect();}@Override public void onClose(){collect();minecraft.setScreen(previous);}@Override public boolean isPauseScreen(){return false;}
 @Override public boolean mouseScrolled(double x,double y,double dx,double dy){scroll=Math.max(0,Math.min(maxScroll,scroll+(int)(-dy*24)));return true;}
 private List<Component> lines(){List<Component> list=new ArrayList<>();Map<String,String> data=new TreeMap<>();if(host){JsonObject d=DedicatedPanelService75.local();for(var e:d.entrySet())try{data.put(e.getKey(),e.getValue().getAsString());}catch(Exception ignored){}}else data.putAll(DedicatedPanelService75.remote());if(data.containsKey("phase"))list.add(tr("phase."+data.get("phase")));if(data.containsKey("generation"))list.add(tr("generation",data.get("generation")));if(data.containsKey("failureCode")&&!data.get("failureCode").isEmpty())list.add(tr("error."+switch(data.get("failureCode")){case "DEDICATED75_WAIT_FOR_JOINED"->"wait_joined";case "DEDICATED75_RELEASE_CHAIN"->"chain";case "DEDICATED75_ACTIVE_ROUND"->"active_round";case "DEDICATED75_STAGE_CHANGED"->"changed";case "DEDICATED75_REQUEST_PENDING"->"pending";case "DEDICATED75_STALE_GENERATION"->"stale";default->"generic";}));if(data.containsKey("reason")&&!data.get("reason").isEmpty())list.add(Component.literal(data.get("reason")));
  try{JsonObject c=JsonParser.parseString(data.getOrDefault("control","{}")).getAsJsonObject();if(c.has("installed"))list.add(tr("players",c.get("installed").getAsString(),c.get("total").getAsString(),c.get("needed").getAsString(),c.get("joined").getAsString()));}catch(Exception ignored){}
  try{JsonObject delta=JsonParser.parseString(data.getOrDefault("delta","{}")).getAsJsonObject();for(String key:List.of("added","changed","removed")){if(delta.has(key+"Count")){list.add(tr("delta."+key,delta.get(key+"Count").getAsString()));for(JsonElement name:delta.getAsJsonArray(key))list.add(Component.literal("  "+name.getAsString()));}}}catch(Exception ignored){}
  try{JsonArray h=JsonParser.parseString(data.getOrDefault("history","[]")).getAsJsonArray();list.add(tr("history"));for(JsonElement e:h){JsonObject r=e.getAsJsonObject();list.add(tr("history_row",r.get("source").getAsString(),r.get("target").getAsString(),tr("event."+r.get("phase").getAsString())));}}catch(Exception ignored){}if(DedicatedPanelService75.result().equals("START_FROM_TERMINAL"))list.add(tr("start_external_hint"));list.add(tr(host?"host_hint":"remote_hint"));return list;
 }
 @Override public void render(GuiGraphics g,int mx,int my,float dt){g.fill(0,0,width,height,0xF0151820);g.drawCenteredString(font,title,width/2,10,0xFFFFFFFF);g.drawCenteredString(font,tr("result."+DedicatedPanelService75.result()),width/2,23,0xFFCCD0DC);int y=58;if(host&&page==1){for(String key:List.of("source","root","export","mods")){g.drawString(font,tr(key),left,y+6,0xFFCCD0DC,false);y+=24;}}if(label!=null)g.drawString(font,tr("label"),left,y+6,0xFFCCD0DC,false);
  List<net.minecraft.util.FormattedCharSequence> lines=new ArrayList<>();for(Component c:lines())lines.addAll(font.split(c,w-8));int row=font.lineHeight+3;int viewport=Math.max(0,bottom-top);maxScroll=Math.max(0,lines.size()*row-viewport);scroll=Math.min(scroll,maxScroll);if(viewport>0){g.enableScissor(left,top,left+w,bottom);int at=top-scroll;for(var line:lines){if(at+row>=top&&at<bottom)g.drawString(font,line,left,at,0xFFCCD0DC,false);at+=row;}g.disableScissor();}super.render(g,mx,my,dt);
 }
}
